SELECT CASE WHEN o.amount >= 1390 THEN 'high' WHEN o.amount >= 770 THEN 'mid' ELSE 'low' END AS amount_bucket, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(p.method))) AS method_values, COUNT(CASE WHEN p.method = 'card' THEN 1 END) AS card_count FROM payments p JOIN orders o ON p.order_id = o.id GROUP BY CASE WHEN o.amount >= 1390 THEN 'high' WHEN o.amount >= 770 THEN 'mid' ELSE 'low' END ORDER BY method_values;
